referenceSolutions.javascript:
function duplicateCarriageTotalReceipt(readings, k) {
  const a=readings; let out=[];
  let write=0;for(let read=0;read<a.length;read++)if(write===0||a[read]!==a[write-1])a[write++]=a[read];out=a.slice(0,write);
  return out.reduce((s,x)=>s+x,0);
}

